vendor/cleanyourtv/launcher/build-and-in:
param([string]$TvHost, [string]$StockLauncher, [switch]$HomeKeyService, [switch]$InputKeyService)
Set-Content -LiteralPath ran.txt -Value ""
$hk = if ($HomeKeyService) { 1 } else { 0 }
Add-Content -LiteralPath $env:FAKE_BIN_LOG -Value "upstream STOCK_LAUNCHER=$StockLauncher homekey=$hk"
$code = if ($env:FAKE_UPSTREAM_EXIT) { [int]$env:FAKE_UPSTREAM_EXIT } else { 1 }
exit $code
